sql_calls.sql:
SELECT COUNT(DISTINCT bill_id) AS distinct_bills
FROM payments.pos_payments
WHERE ts >= '2026-05-04' AND ts < '2026-06-01';

SELECT COUNT(DISTINCT bill_id) AS distinct_bills
FROM store.pos_lines
WHERE bill_ts >= '2026-05-04' AND bill_ts < '2026-06-01';

SELECT sku, name
FROM store.products
WHERE name ILIKE '%toned%milk%' OR name ILIKE '%milk%toned%';

SELECT DISTINCT kind, resolution
FROM payments.customer_complaints
ORDER BY kind, resolution;

SELECT DISTINCT till_status
FROM payments.pos_payments
ORDER BY till_status;

SELECT *
FROM warehouse.pallets
WHERE sscc IN (
    SELECT sscc FROM warehouse.shipping_notice_lines WHERE sku = 'ATTA-WW-5KG'
)
LIMIT 20;

SELECT *
FROM store.fresh_deliveries
LIMIT 10;

SELECT *
FROM store.goods_receipts
LIMIT 10;

SELECT COUNT(*) AS pallets_received
FROM store.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT COUNT(DISTINCT sscc) AS distinct_pallets
FROM store.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT COUNT(DISTINCT date) AS distinct_days
FROM store.write_offs
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT COUNT(*) AS receipt_lines
FROM store.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT COUNT(*) AS shipments_arrived
FROM warehouse.shipments
WHERE arrived_ts >= '2026-05-01' AND arrived_ts < '2026-06-01';

SELECT sku, name, pack, price_inr
FROM store.products
WHERE name ILIKE '%atta%' AND pack ILIKE '%5%kg%';

SELECT DISTINCT tender
FROM payments.pos_payments
ORDER BY tender;

SELECT DISTINCT status
FROM payments.psp_upi_report
ORDER BY status;

SELECT DISTINCT sku, name
FROM store.products
ORDER BY sku;

SELECT sku, name, pack
FROM store.products
WHERE name ILIKE '%atta%' AND pack ILIKE '%5%kg%';

SELECT COUNT(DISTINCT l.bill_id) as bills_started
FROM store.pos_lines l
WHERE l.bill_ts >= '2026-06-01' AND l.bill_ts < '2026-07-01';

SELECT DISTINCT till_status
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT DISTINCT trigger
FROM store.stock_counts
WHERE count_ts >= '2026-06-01' AND count_ts < '2026-07-01';

SELECT DISTINCT reason
FROM store.write_offs
WHERE date >= '2026-06-01' AND date < '2026-07-01';

SELECT sku, name, pack
FROM store.products
WHERE name ILIKE '%atta%';

SELECT sku, name, pack, price_inr, cost_inr
FROM store.products
WHERE sku IN ('ATTA-WW-1KG', 'ATTA-WW-5KG', 'ATTA-WW-10KG');

SELECT *
FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';

SELECT DISTINCT kind
FROM payments.customer_complaints
ORDER BY kind;

SELECT SUM(amount_inr) as total_upi_refunds
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT COUNT(*) as total_complaints, COUNT(DISTINCT kind) as distinct_kinds
FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';

SELECT sku, name, pack, flow
FROM store.products
WHERE name ILIKE '%toned%milk%' OR name ILIKE '%milk%toned%';

SELECT DISTINCT method
FROM store.forecasts
WHERE date >= '2026-06-01' AND date <= '2026-06-30';
